import itertools
def sat(n,S,F,B):
    D=range(n); b=lambda y,x:B[y*n+x]; P=lambda x:S[x] and F[x]
    st=all((not P(x)) or any(b(y,x) and not F[y] for y in D) for x in D)
    o={'A':any(all((not P(x)) or (b(y,x) and not F[y]) for x in D) for y in D),
       'B':st,
       'C':all(not(P(x) and all((not b(y,x)) or F[y] for y in D)) for x in D),
       'D':all(any((not P(x)) or (b(y,x) and not F[y]) for y in D) for x in D)}
    return st,o
eq={k:True for k in 'BCD'}
for n in (1,2,3):
    for S in itertools.product([0,1],repeat=n):
        for F in itertools.product([0,1],repeat=n):
            for B in itertools.product([0,1],repeat=n*n):
                st,o=sat(n,S,F,B)
                for k in eq: eq[k]&=(o[k]==st)
